using System.Text;
using System.Xml;
using System.Xml.Linq;
using Watch.Domain.Face;

namespace FaceStudio;

/// <summary>One generated file, at its path (with forward slashes) under the face's folder.</summary>
public sealed record FaceFile(string Path, byte[] Bytes);

/// <summary>
/// Every file of the face, as aapt2 packs them, in <see cref="Folder"/>. They are committed, like
/// IconStudio's output, and <c>FaceFilesTests.TheCommittedFaceIsCurrent</c> holds them to the tool.
/// </summary>
public static class FaceFiles
{
    public const string Folder = "Watch/Point.Face";

    private const string Notice = " Generated by Tools/FaceStudio from Watch.Domain. Do not edit; run the tool. ";

    public static IReadOnlyList<FaceFile> All(string repoRoot)
    {
        var face = FaceDocument.Build();
        var problems = FaceSchema.Problems(face, repoRoot);
        if (problems.Count > 0)
        {
            throw new InvalidOperationException(
                $"The face does not meet the Watch Face Format {PointFace.FormatVersion} schema:{Environment.NewLine}{string.Join(Environment.NewLine, problems)}");
        }

        var files = new List<FaceFile>
        {
            Xml("AndroidManifest.xml", FaceManifest.Manifest()),
            Xml("res/raw/watchface.xml", face),
            Xml("res/xml/watch_face_info.xml", FaceManifest.Info()),
            Xml("res/values/strings.xml", FaceManifest.Strings()),
            new($"res/font/{PointFace.FontResource}.ttf", File.ReadAllBytes(Path.Combine(repoRoot, "Watch", "Fonts", PointFace.FontFile))),
            new("res/drawable-nodpi/preview.png", Preview.Draw().Png()),
        };

        foreach (var afternoon in new[] { false, true })
        {
            var radius = (afternoon ? FaceGeometry.AfternoonRadius : FaceGeometry.MorningRadius) * PointFace.Canvas / 2.0;
            for (var sides = 3; sides <= 12; sides++)
            {
                files.Add(new($"res/drawable-nodpi/{Masks.Name(sides, afternoon)}.png", Masks.Draw(sides, radius).Png()));
            }
        }

        return files;
    }

    /// <summary>Writes every file into <paramref name="outputFolder"/> and removes any it no longer makes.</summary>
    public static void Write(string repoRoot, string outputFolder)
    {
        var files = All(repoRoot);
        var wanted = files.Select(file => Path.GetFullPath(Path.Combine(outputFolder, file.Path))).ToHashSet();

        var resources = Path.Combine(outputFolder, "res");
        if (Directory.Exists(resources))
        {
            foreach (var stale in Directory.EnumerateFiles(resources, "*", SearchOption.AllDirectories).Where(path => !wanted.Contains(Path.GetFullPath(path))))
            {
                File.Delete(stale);
            }
        }

        foreach (var file in files)
        {
            var path = Path.Combine(outputFolder, file.Path);
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllBytes(path, file.Bytes);
        }
    }

    private static FaceFile Xml(string path, XDocument document)
    {
        var copy = new XDocument(new XDeclaration("1.0", "utf-8", null), new XComment(Notice), document.Root);
        var settings = new XmlWriterSettings
        {
            Encoding = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false),
            Indent = true,
            IndentChars = "  ",
            NewLineChars = "\n",
        };
        using var stream = new MemoryStream();
        using (var writer = XmlWriter.Create(stream, settings))
        {
            copy.Save(writer);
        }
        stream.WriteByte((byte)'\n');
        return new FaceFile(path, stream.ToArray());
    }
}
